<?php declare(strict_types=1);namespace NpmGateway\Services;use NpmGateway\Contracts\{ClockInterface,InitializationTransactionInterface};use NpmGateway\Exceptions\Domain\{CommunityActionPropertyForbiddenException,RmAuditStateConflictException};use NpmGateway\Http\AuthenticatedRequestContext;use NpmGateway\Notifications\RmAuditEmailSender;use NpmGateway\Repositories\RmAuditRepository;use NpmGateway\Support\PublicIdGenerator;use NpmGateway\ValueObjects\{AuthenticatedUser,CommunityActionContext};
final class RmAuditService{public function __construct(private readonly RmAuditRepository$r,private readonly RmAuditValidator$v,private readonly InitializationTransactionInterface$tx,private readonly PublicIdGenerator$ids,private readonly ClockInterface$clock,private readonly AuditService$a,private readonly RmAuditEmailSender$mail,private readonly PropertyAccessService$access){}
 public function create(array$post,AuthenticatedUser$actor):array{$d=$this->v->creation($post);$property=$this->r->property($d['property']);if(!$property)throw new \NpmGateway\Exceptions\Domain\InvalidRmAuditException(['property_public_id'=>'Select a valid active community.'],$post);$at=$this->now();$public=$this->ids->generate();$this->tx->begin();try{$id=$this->r->insert(['public_id'=>$public,'property_id'=>(int)$property['id'],'actor_id'=>$actor->id,'at'=>$at]+$d);$this->r->event($id,$this->ids->generate(),'submitted',$actor->id,null,$at);$this->audit('submitted',$public,(string)$property['public_id'],$actor,'new_to_open',$at);$this->tx->commit();}catch(\Throwable$e){$this->tx->rollback();throw$e;}$audit=$this->r->detail($public);return['public_id'=>$public,'email_sent'=>$audit!==null&&$this->mail->submitted($audit)];}
 public function complete(CommunityActionContext$c,string$public):bool{$at=$this->now();$this->tx->begin();try{if(!$this->access->canAccessProperty(new AuthenticatedRequestContext($c->user,''),$c->propertyId))throw new CommunityActionPropertyForbiddenException();$r=$this->r->detail($public,$c->propertyId,true);if(!$r)throw new \OutOfBoundsException();$from=(string)$r['status'];if(!in_array($from,['open','returned'],true)||!$this->r->transition((int)$r['id'],[$from],'completed',$c->userId,$at))throw new RmAuditStateConflictException();$this->r->event((int)$r['id'],$this->ids->generate(),'completed',$c->userId,null,$at);$this->audit('completed',$public,$c->propertyPublicId,$c->user,$from.'_to_completed',$at);$this->tx->commit();}catch(\Throwable$e){$this->tx->rollback();throw$e;}$done=$this->r->detail($public,$c->propertyId);return$done!==null&&$this->mail->completed($done);}
 public function returnAudit(string$public,array$post,AuthenticatedUser$actor):bool{$comments=$this->v->returning($post);$at=$this->now();$this->tx->begin();try{$r=$this->r->detail($public,null,true);if(!$r)throw new \OutOfBoundsException();if($r['status']!=='completed'||!$this->r->transition((int)$r['id'],['completed'],'returned',$actor->id,$at))throw new RmAuditStateConflictException();$this->r->event((int)$r['id'],$this->ids->generate(),'returned',$actor->id,$comments,$at);$this->audit('returned',$public,(string)$r['property_public_id'],$actor,'completed_to_returned',$at);$this->tx->commit();}catch(\Throwable$e){$this->tx->rollback();throw$e;}$done=$this->r->detail($public);return$done!==null&&$this->mail->returned($done,$comments);}
 private function audit(string$type,string$public,string$property,AuthenticatedUser$actor,string$transition,string$at):void{$this->a->record('rm_audit.'.$type,$actor->id,$actor->employeeId,$actor->publicId,'RM Audit lifecycle event recorded.',['audit_public_id'=>$public,'property_public_id'=>$property,'actor_public_id'=>$actor->publicId,'status_transition'=>$transition,'event_type'=>$type],$at);}private function now():string{return$this->clock->now()->format('Y-m-d H:i:s');}}
